
<!-- Imagine Puzzle -->
<template>

  <div>
    <div>点击节点可以标红该节点相连的其它节点。</div>
    <div class="imagine-input-container" 
         :style="{ left: containerPosition.x + 'px', top: containerPosition.y + 'px' }"
         @mousedown="startDrag"
         ref="dragContainer">
      <input type="text" v-model="guess" @keyup.enter="submitGuess" placeholder="请输入答案，按回车提交" />
      <span v-if="errormsg">{{ errormsg }}</span>
    </div>
    <div><svg id="imagineSvg" width="1600" height="1500" style="background-color: white;"></svg></div>
  </div>

</template>

<style>

.imagine-input-container {
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  position: fixed;
  width: max-content;
  padding: 10px;
  box-shadow: 0 0 10px 0 rgba(0, 0, 0, 0.1);
  cursor: move;
  user-select: none;
  z-index: 1000;
  background-color: white;
  border-radius: 7px;
}
.imagine-input-container>input {
  width: 250px;
  height: 100%;
  border: 1px solid #ccc;
  outline: none;
  font-size: 16px;
  padding: 5px;
  border-radius: 5px;
}
.imagine-input-container>span {
  margin-top: 5px;
  color: maroon;
  font-size: 12px;
  display: block;
}


.link {
  stroke: rgba(50, 50, 50);
  stroke-opacity: 0.2;
  stroke-width: 1px;
}

.selectedLink {
  stroke: rgba(255, 0, 0);
  stroke-opacity: 0.8;
  stroke-width: 1px;
}

.specialLabel {
  fill: blue
}

.label {
  fill: green
}

.highlightLabel {
  fill: red
}

.node {
  fill: black;
}

</style>

